#pragma once
// Place coordinates locate modern reference areas. Auxiliary vertices only guide
// a schematic connection and are never presented as documented visits.
inline Stop routePlace(double lat,double lon,const wchar_t* zh,const wchar_t* en,const wchar_t* date=L""){return {{lat,lon},zh,en,WaypointKind::Milestone,date};}
inline Stop routeGuide(double lat,double lon){return {{lat,lon},L"路径辅助点",L"Connection guide",WaypointKind::Auxiliary,L""};}
inline Stop routeUncertain(double lat,double lon,const wchar_t* zh,const wchar_t* en){return {{lat,lon},zh,en,WaypointKind::Uncertain,L""};}
inline const wchar_t* travelModeLabel(TravelMode mode,bool en){
    if(mode==TravelMode::Sea)return en?L"Sea voyage":L"航海";
    if(mode==TravelMode::Mixed)return en?L"Land and water":L"水陆行程";
    if(mode==TravelMode::Polar)return en?L"Polar expedition":L"极地探险";
    return en?L"Land journey":L"陆上行程";
}
inline const wchar_t* waypointKindLabel(WaypointKind kind,bool en){
    if(kind==WaypointKind::Auxiliary)return en?L"Connection guide":L"路径辅助点";
    if(kind==WaypointKind::Uncertain)return en?L"Uncertain locality":L"位置有争议";
    if(kind==WaypointKind::LoggedPosition)return en?L"Logged sea position":L"航海日志位置";
    if(kind==WaypointKind::ReferenceLocality)return en?L"Approximate source locality":L"来源地点参考点";
    return en?L"Selected historical place":L"已选历史地点";
}
